def resource(rel: str) -> str:
    """Locate bundled assets both when run from source and inside the PyInstaller build."""
    return str(Path(getattr(sys, "_MEIPASS", Path(__file__).resolve().parent)) / rel)


LOGO_B64 = ""


def logo_pixmap() -> QPixmap:
    pm = QPixmap(resource("assets/logo.png"))
    if pm.isNull():                       # embedded copy: works even without the assets folder
        pm.loadFromData(base64.b64decode(LOGO_B64))
    return pm


def logo_label(size: int) -> QLabel:
    lbl = QLabel(); lbl.setFixedSize(size, size); lbl.setAlignment(Qt.AlignCenter)
    pm = logo_pixmap()
    if not pm.isNull():
        pm = pm.scaled(size * 2, size * 2, Qt.KeepAspectRatio, Qt.SmoothTransformation)
        pm.setDevicePixelRatio(2.0)             # crisp on high-DPI screens
        lbl.setPixmap(pm)
    return lbl

